func (q *Queries) RotateEndpointSecret(ctx context.Context, arg RotateEndpointSecretParams) (Endpoint, error) {
	row := q.db.QueryRow(ctx, rotateEndpointSecret,
		arg.Secret,
		arg.PreviousSecret,
		arg.PreviousExpiresAt,
		arg.OrgID,
		arg.ID,
	)
	var i Endpoint
	err := row.Scan(
		&i.OrgID,
		&i.ID,
		&i.Url,
		&i.Description,
		&i.EventTypes,
		&i.Enabled,
		&i.Secret,
		&i.PreviousSecret,
		&i.PreviousExpiresAt,
		&i.SecretRotatedAt,
		&i.CreatedBy,
		&i.CreatedAt,
		&i.LastModifiedBy,
		&i.LastModifiedAt,
	)
	return i, err
}

const subscribedEndpoints = `-- name: SubscribedEndpoints :many
SELECT id FROM endpoints
WHERE org_id = $1 AND enabled
  AND (cardinality(event_types) = 0 OR $2::text = ANY (event_types))
ORDER BY created_at, id
`

type SubscribedEndpointsParams struct {
	OrgID uuid.UUID
	Type  string
}

// The enabled endpoints that receive a type: those that name it, and those
// that name none (every type).
func (q *Queries) SubscribedEndpoints(ctx context.Context, arg SubscribedEndpointsParams) ([]uuid.UUID, error) {
	rows, err := q.db.Query(ctx, subscribedEndpoints, arg.OrgID, arg.Type)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []uuid.UUID{}
	for rows.Next() {
		var id uuid.UUID
		if err := rows.Scan(&id); err != nil {
			return nil, err
		}
		items = append(items, id)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const updateEndpoint = `-- name: UpdateEndpoint :one
UPDATE endpoints
SET url = $1, description = $2, event_types = $3, enabled = $4
WHERE org_id = $5 AND id = $6
RETURNING org_id, id, url, description, event_types, enabled, secret, previous_secret, previous_expires_at, secret_rotated_at, created_by, created_at, last_modified_by, last_modified_at
`

type UpdateEndpointParams struct {
	Url         string
	Description string
	EventTypes  []string
	Enabled     bool
	OrgID       uuid.UUID
	ID          uuid.UUID
}

func (q *Queries) UpdateEndpoint(ctx context.Context, arg UpdateEndpointParams) (Endpoint, error) {
	row := q.db.QueryRow(ctx, updateEndpoint,
		arg.Url,
		arg.Description,
		arg.EventTypes,
		arg.Enabled,
		arg.OrgID,
		arg.ID,
	)
	var i Endpoint
	err := row.Scan(
		&i.OrgID,
		&i.ID,
		&i.Url,
		&i.Description,
		&i.EventTypes,
		&i.Enabled,
		&i.Secret,
		&i.PreviousSecret,
		&i.PreviousExpiresAt,
		&i.SecretRotatedAt,
		&i.CreatedBy,
		&i.CreatedAt,
		&i.LastModifiedBy,
		&i.LastModifiedAt,
	)
	return i, err
}
